<script setup>
import { computed, onMounted } from 'vue'
import { useUploadStore } from '../stores/uploadStore'
import PdfReportButton from '../components/PdfReportButton.vue'
const upload = useUploadStore()
const arquivo = computed(() => upload.arquivo?.name || upload.lote?.arquivoNome || upload.lote?.arquivo_nome || 'Último lote processado')
onMounted(() => { if (!upload.estatisticas) upload.carregarUltimoLote() })
</script>

<template>
  <main class="page-wrap report-page">
    <header class="page-head"><div><p class="page-kicker">ANÁLISE DA CARTEIRA</p><h1 class="page-title">Relatórios</h1><p class="page-description">Confira as inconsistências e exporte uma análise interpretativa do lote.</p></div><div class="report-actions"><PdfReportButton :estatisticas="upload.estatisticas" :lote="upload.lote" :arquivo="arquivo" :erros="upload.erros"/><router-link to="/upload" class="btn-primary">＋ Nova importação</router-link></div></header>
    <div class="report-file glass-panel"><span class="report-file-icon">XLS</span><div><small>ARQUIVO ANALISADO</small><b>{{ arquivo }}</b></div><span v-if="upload.lote" class="report-lote">LOTE #{{ upload.lote.id }}</span></div>
    <template v-if="upload.temResultado">
      <section class="report-metrics"><article class="glass-panel"><span class="report-metric-symbol valid">✓</span><p>Total de registros</p><b>{{ upload.totalRegistros.toLocaleString('pt-BR') }}</b></article><article class="glass-panel"><span class="report-metric-symbol valid">✓</span><p>Válidos</p><b>{{ upload.registrosValidos.toLocaleString('pt-BR') }}</b></article><article class="glass-panel"><span class="report-metric-symbol attention">!</span><p>Linhas com erro</p><b>{{ upload.registrosComErro.toLocaleString('pt-BR') }}</b></article><article class="glass-panel"><span class="report-metric-symbol attention">·</span><p>Ocorrências</p><b>{{ upload.totalErros.toLocaleString('pt-BR') }}</b></article></section>
      <section class="report-grid">
        <article class="glass-panel report-summary"><div class="report-panel-heading"><div><p class="eyebrow">RESUMO</p><h2 class="section-title">Ocorrências por tipo</h2></div><span class="summary-count">{{ upload.errosPorTipo.length }} tipos</span></div><div v-if="upload.errosPorTipo.length" class="error-type-list"><div v-for="item in upload.errosPorTipo" :key="item.tipo"><span>{{ item.tipo }}</span><b>{{ item.total }}</b></div></div><div v-else class="approved-state"><span>✓</span><div><b>Nenhuma inconsistência</b><p>Os registros enviados passaram pelas validações.</p></div></div></article>
        <article class="glass-panel report-details"><div class="report-panel-heading"><div><p class="eyebrow">LINHA A LINHA</p><h2 class="section-title">Detalhes da validação</h2></div><span class="summary-count">{{ upload.erros.length }} itens</span></div><div v-if="upload.erros.length" class="report-table-wrap"><table class="report-table"><thead><tr><th>Linha</th><th>Campo</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr v-for="erro in upload.erros" :key="erro.id"><td><span class="line-number">{{ erro.linha }}</span></td><td>{{ erro.campo }}</td><td><span class="error-tag">{{ erro.tipo }}</span></td><td>{{ erro.descricao }}</td></tr></tbody></table></div><div v-else class="approved-state detail-approved"><span>✓</span><div><b>Planilha conferida</b><p>Nenhuma pendência encontrada neste processamento.</p></div></div></article>
      </section>
    </template>
    <section v-else class="glass-panel report-empty"><span class="empty-orbit">✓</span><p class="page-kicker">NENHUM PROCESSAMENTO</p><h2>Seu relatório aparece aqui depois da importação.</h2><p>Envie uma planilha para analisar os registros e ver o resultado da validação.</p><router-link to="/upload" class="btn-primary">Ir para importação <span>↗</span></router-link></section>
  </main>
</template>

